  });

  it("addGsapTween dispatch returns EMPTY when no timeline — no dangling tl call emitted", () => {
    const parsed = freshNoTimeline();
    const scriptBefore = getScript(parsed);
    const result = applyOp(parsed, {
      type: "addGsapTween",
      target: "hf-box",
