describe("validateOp with GSAP script", () => {
  it("addGsapTween → ok:true", () => {
    expect(
      validateOp(fresh(), {
        type: "addGsapTween",
        target: "hf-box",
        tween: { method: "to", duration: 0.3, properties: { x: 100 } },
      }).ok,
